import{_ as a}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as n,C as s,o as l,c as i,a2 as o,j as r,a as d,E as c}from"./chunks/framework.Dx-TCpNt.js";const x=JSON.parse('{"title":"コマ分割ワークベンチ","description":"コマ分割ワークベンチは、ページを構造化データに変える場所です。自動検出はあくまで出発点にすぎず、ワークベンチはそれをすばやく、取り消し可能な形で修正するために作られています。","frontmatter":{"description":"コマ分割ワークベンチは、ページを構造化データに変える場所です。自動検出はあくまで出発点にすぎず、ワークベンチはそれをすばやく、取り消し可能な形で修正するために作られています。"},"headers":[],"relativePath":"ja/guide/panels.md","filePath":"ja/guide/panels.md","lastUpdated":1794725747000}'),g={name:"ja/guide/panels.md"};function h(b,t,p,u,m,f){const e=s("Badge");return l(),i("div",null,[t[6]||(t[6]=o('<h1 id="コマ分割ワークベンチ" tabindex="-1">コマ分割ワークベンチ <a class="header-anchor" href="#コマ分割ワークベンチ" aria-label="Permalink to &quot;コマ分割ワークベンチ&quot;">​</a></h1><p>コマ分割ワークベンチは、ページを構造化データに変える場所です。自動検出はあくまで出発点にすぎず、ワークベンチはそれをすばやく、取り消し可能な形で修正するために作られています。</p><figure class="shot"><img src="'+a+'" alt="4つのコマが検出されたコマ分割ワークベンチ。リサイズハンドルと注釈ツールバーを表示"><figcaption>検出されたコマは、下地画像の上に番号付きの枠として描画されます。選択中の枠には8つのリサイズハンドルが表示されます。注釈ツールバーはコマのツールの下にあります。</figcaption></figure><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>以降のすべての機能はコマに依存します。比較読み、コマ単位のノート、コマの PNG エクスポート、HTML エクスポートです。枠が誤っていると、後続のすべてが誤ります。自動検出はほとんどのページを正しく処理しますが、扉ページ、見開きページ、端の細い帯、特殊なレイアウトは必ず手作業が必要になります。</p><h2 id="ツールバーの各コントロール" tabindex="-1">ツールバーの各コントロール <a class="header-anchor" href="#ツールバーの各コントロール" aria-label="Permalink to &quot;ツールバーの各コントロール&quot;">​</a></h2><h3 id="_1行目-—-下地画像と分割" tabindex="-1">1行目 — 下地画像と分割 <a class="header-anchor" href="#_1行目-—-下地画像と分割" aria-label="Permalink to &quot;1行目 — 下地画像と分割&quot;">​</a></h3><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th><th>補足</th></tr></thead><tbody><tr><td><strong>下地画像</strong> セレクター</td><td>表示し、検出に使う言語の画像を選びます。</td><td>コマの矩形はページの全言語で共有されるため、変わるのは描画の対象となる画像だけです。</td></tr><tr><td>検出器チップ</td><td>現在のコマを生成したアルゴリズムのバージョン（例：<code>xycut-1.3</code>、<code>layout:&lt;id&gt;</code>、<code>plugin:&lt;name&gt;</code>）を表示します。</td><td><code>旧データ</code> は、ページ JSON がバージョン追跡より前のものであることを示します。</td></tr><tr><td>状態テキスト</td><td>コマが <em>自動</em>、<em>テンプレート適用</em>、<em>プラグイン適用</em>、<em>手動編集</em> のどれか、保存回数、最後の編集概要を表示します。</td><td>これは編集カウンターであり、監査ログではありません。</td></tr><tr><td><strong>自動分割</strong></td><td>下地画像に対して検出を実行し、現在のコマを置き換えます。</td><td>検出中、またはページに画像がないときは無効になります。再実行すると手作業の編集は破棄されます。</td></tr><tr><td><strong>コマを追加</strong></td><td>ページ中央付近に既定のコマを追加します。</td><td>より速い方法：空白をダブルクリックします。</td></tr><tr><td><strong>結合</strong>（n）</td><td>選択したコマを <code>source: &quot;merged&quot;</code> の1つの枠に結合します。</td><td>2つ以上のコマを選択すると有効になります。</td></tr><tr><td><strong>削除</strong></td><td>選択したコマと、そのコマに紐付くノートを削除します。</td><td><code>Delete</code> / <code>Backspace</code> と同じです。</td></tr></tbody></table><h3 id="_1行目-—-保存" tabindex="-1">1行目 — 保存 <a class="header-anchor" href="#_1行目-—-保存" aria-label="Permalink to &quot;1行目 — 保存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>自動</strong></td><td>変更から約0.7秒後に自動保存します。</td></tr><tr><td><strong>確認</strong></td><td><strong>✓</strong> をクリックするか <code>Enter</code> を押すまで、編集を未保存のまま保持します。<strong>×</strong> または <code>Esc</code> で破棄し、最後に保存した状態に戻します。</td></tr><tr><td><code>↶</code> / <code>↷</code></td><td>元に戻す / やり直す（<code>Ctrl+Z</code>、<code>Ctrl+Shift+Z</code>、<code>Ctrl+Y</code>）。</td></tr><tr><td><strong>✓</strong></td><td>未保存のページを保存します（確認モードのみ）。</td></tr><tr><td><strong>×</strong></td><td>未保存の編集を破棄します（確認モードのみ）。</td></tr><tr><td><strong>未保存</strong> フラグ</td><td>確認モードで、未保存の変更がある間に表示されます。</td></tr><tr><td><strong>番号</strong></td><td>コマのインデックスバッジを表示または非表示にします。</td></tr></tbody></table><p>保存モードはブラウザに記憶されます。上部バーには常に現在の状態（<em>保存済み</em>、<em>保存中…</em>、<em>保存待ち</em>、<em>未保存の変更</em>）が表示されます。</p><h3 id="_1行目-—-ズーム" tabindex="-1">1行目 — ズーム <a class="header-anchor" href="#_1行目-—-ズーム" aria-label="Permalink to &quot;1行目 — ズーム&quot;">​</a></h3><p><code>−</code> / パーセント / <code>＋</code> のコントロールで、ステージのズームを50%から300%まで15%刻みで変更します。ズームは表示だけの設定です。コマの座標は <code>0..1</code> に正規化されており、変化しません。</p><h3 id="_2行目-—-数値の矩形" tabindex="-1">2行目 — 数値の矩形 <a class="header-anchor" href="#_2行目-—-数値の矩形" aria-label="Permalink to &quot;2行目 — 数値の矩形&quot;">​</a></h3><p>コマを1つだけ選択すると、2行目に <strong>コマ座標</strong> と4つのパーセント入力が表示されます。</p><table tabindex="0"><thead><tr><th>フィールド</th><th>意味</th></tr></thead><tbody><tr><td><code>X</code></td><td>左端（ページ幅に対する割合）。</td></tr><tr><td><code>Y</code></td><td>上端（ページ高さに対する割合）。</td></tr><tr><td><code>W</code></td><td>幅（ページ幅に対する割合）。</td></tr><tr><td><code>H</code></td><td>高さ（ページ高さに対する割合）。</td></tr></tbody></table><p>値を入力するとコマがすぐに更新されます。ページ外の値は保存時に範囲内に丸められます。</p><h3 id="_2行目-—-グリッド生成" tabindex="-1">2行目 — グリッド生成 <a class="header-anchor" href="#_2行目-—-グリッド生成" aria-label="Permalink to &quot;2行目 — グリッド生成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>フィールド</th><th>範囲</th><th>意味</th></tr></thead><tbody><tr><td><strong>行</strong></td><td>1〜8</td><td>行数。</td></tr><tr><td><strong>列</strong></td><td>1〜6</td><td>列数。</td></tr><tr><td><strong>間隔</strong></td><td>0〜8 %</td><td>セル間の余白（ページに対する割合）。</td></tr><tr><td><strong>グリッドを生成</strong></td><td>—</td><td>現在のコマを均等分割したグリッドで置き換えます。</td></tr></tbody></table><p>雑誌の固定レイアウトが続く話にはグリッドを使い、同じレイアウトが正確に繰り返される場合は <strong>コマテンプレート</strong> を使います。</p><h3 id="_2行目-—-テンプレートと-json" tabindex="-1">2行目 — テンプレートと JSON <a class="header-anchor" href="#_2行目-—-テンプレートと-json" aria-label="Permalink to &quot;2行目 — テンプレートと JSON&quot;">​</a></h3><p><strong>コマテンプレート</strong> は現在のページの矩形を記録します。</p><ol><li><strong>コマテンプレート</strong> を開き、名前を入力して <strong>このページをテンプレートに保存</strong> をクリックします。</li><li>テンプレートを選択し、<strong>このページに適用</strong> または <strong>話全体に適用</strong> をクリックします。</li><li>話に適用すると既存のコマが上書きされるため、確認を求められます。</li></ol><p>新しいページのコマ数がテンプレートと同じ場合、コマ単位のノートは読み順で再マッピングされます。コマ数が異なる場合、コマノートは誤ったコマに黙って結び付くのではなく破棄されますが、ページノートは常に保持されます。テンプレートは <code>data/templates/panel.json</code> に保存されます。</p><p><strong>JSON パスをコピー</strong> は <code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code> をコピーします。このファイルを手で編集することも可能で、サーバーは読み込み時に矩形を正規化し、欠けた id を補修し、ぶら下がった参照を削除します。</p><h2 id="キャンバス上のマウスとキーボード" tabindex="-1">キャンバス上のマウスとキーボード <a class="header-anchor" href="#キャンバス上のマウスとキーボード" aria-label="Permalink to &quot;キャンバス上のマウスとキーボード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>ジェスチャー</th></tr></thead><tbody><tr><td>コマを移動</td><td>枠の本体をドラッグします。</td></tr><tr><td>リサイズ</td><td>8つのハンドルのいずれかをドラッグします。</td></tr><tr><td>コマをすばやく追加</td><td>空白をダブルクリックします。</td></tr><tr><td>コマを正確に描く</td><td>空白の上をドラッグします。</td></tr><tr><td>正方形に固定</td><td>描画中に <code>Shift</code> を押します。</td></tr><tr><td>吸着を無効にする</td><td>描画またはドラッグ中に <code>Alt</code> を押します。</td></tr><tr><td>現在の枠をキャンセル</td><td><code>Esc</code>。</td></tr><tr><td>複数選択</td><td><code>Ctrl</code> クリックまたは <code>Shift</code> クリックで枠を選びます。</td></tr><tr><td>微調整</td><td>矢印キーで選択範囲を0.2%移動します。<code>Shift</code> + 矢印で1%移動します。</td></tr><tr><td>削除</td><td><code>Delete</code> または <code>Backspace</code>。</td></tr><tr><td>保存 / 破棄（確認モード）</td><td><code>Enter</code> / <code>Esc</code>。</td></tr></tbody></table><p>すべての座標はページに対して正規化されるため、ズームレベルやエクスポート解像度が変わってもコマは同じ位置にとどまります。</p><h2 id="番号付けと読み方向" tabindex="-1">番号付けと読み方向 <a class="header-anchor" href="#番号付けと読み方向" aria-label="Permalink to &quot;番号付けと読み方向&quot;">​</a></h2><ul><li><strong>番号</strong> でインデックスバッジを切り替えます。</li><li>読み方向はページごとに保存されます：<code>rtl</code>（右から左、上から下）、<code>ltr</code>（左から右、上から下）、<code>ttb</code>（右から左の縦列）。上部バーで変更します。</li><li>コマは明示的な <code>number</code> を持て、自動の読み順を上書きします。それ以外の場合、番号は矩形と方向から導かれます。</li><li>同じ順序が比較リーダー、ノートの一覧、HTML エクスポートでも使われます。</li></ul><div class="tip custom-block"><p class="custom-block-title">まず読み順</p><p>編集を始める前にコマ番号がおかしいと感じたら、まず読み順のセレクターを直してください。JSON で手作業で番号を振り直すこともできますが、方向を変えれば話全体のページがまとめて直ります。</p></div><h2 id="注釈ツール" tabindex="-1">注釈ツール <a class="header-anchor" href="#注釈ツール" aria-label="Permalink to &quot;注釈ツール&quot;">​</a></h2><p>注釈レイヤーは原画の上に描画され、コマとは別に保存されます。</p><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>注釈：表示中 / 非表示</strong></td><td>全体の表示切り替え。非表示にしてもデータは保持され、エクスポートでは隠れます。</td></tr><tr><td><strong>選択と移動</strong></td><td>既存のマークを選択します。ドラッグで移動します。</td></tr><tr><td><strong>矢印</strong></td><td>尾から頭へドラッグします。</td></tr><tr><td><strong>矩形</strong> / <strong>楕円</strong></td><td>矩形または楕円をドラッグで描きます。</td></tr><tr><td><strong>マーカー</strong></td><td>半透明のフリーハンド線。</td></tr><tr><td><strong>フリーハンド</strong></td><td>不透明のペン線。折れ線全体を保持します。</td></tr><tr><td><strong>テキスト</strong></td><td>クリックしてからラベルを入力します。</td></tr><tr><td><strong>番号バッジ</strong></td><td>クリックしてから番号を入力します。</td></tr><tr><td><strong>モザイク</strong></td><td>矩形をドラッグすると、その範囲がピクセル化されます。</td></tr><tr><td><strong>色見本</strong></td><td>新しいマークの色を設定します。マークを選択した状態で色見本をクリックすると、そのマークの色を変更します。</td></tr><tr><td><strong>削除</strong></td><td>選択中のマークを削除します。</td></tr><tr><td><strong>すべて消す</strong></td><td>確認後、ページ上のすべてのマークを削除します。</td></tr></tbody></table><p>適用範囲は選択に従います。コマを1つ選択している場合は「新しい注釈は N コマ目の中に描画」、何も選択していない場合は「新しい注釈はページ全体に描画」と表示されます。<code>Esc</code> で現在のツールを終了するか、マークの選択を解除します。</p><p>エクスポートした HTML と PNG に注釈が含まれるのは、レイヤーが表示されている場合だけです。HTML エクスポートには <strong>原画にコマ枠を描く</strong> オプションもあり、これは注釈とは別です。</p><h2 id="グループ" tabindex="-1">グループ <a class="header-anchor" href="#グループ" aria-label="Permalink to &quot;グループ&quot;">​</a></h2>',37)),r("p",null,[t[0]||(t[0]=d("ページ JSON には ",-1)),t[1]||(t[1]=r("code",null,"groups",-1)),t[2]||(t[2]=d(" フィールド（",-1)),t[3]||(t[3]=r("code",null,"{ id, name, panelIds, number }",-1)),t[4]||(t[4]=d("）があり、読み込み・書き込み・インポート・エクスポートで保持されます。 ",-1)),c(e,{type:"warning",text:"予定"}),t[5]||(t[5]=d(" グループを作成・編集するアプリ内 UI はまだなく、JSON を直接編集した場合にのみ変更できます。",-1))]),t[7]||(t[7]=o('<h2 id="安全な修正手順" tabindex="-1">安全な修正手順 <a class="header-anchor" href="#安全な修正手順" aria-label="Permalink to &quot;安全な修正手順&quot;">​</a></h2><ol><li>ページを開き、自動検出を実行させます。</li><li>明らかな枠を修正します。移動、リサイズ、追加、削除です。</li><li>見開きにまたがる扉ページのコマを結合します。</li><li>保存します（確認モードでは <strong>✓</strong> を押します）。</li><li><strong>比較読み</strong>（<code>C</code>）に切り替え、同じコマに本当に同じ絵が入っているか確認します。</li></ol><p>手作業の編集を失う覚悟がない限り、編集後に <strong>自動分割</strong> を再実行しないでください。</p><figure class="shot"><div class="shot-missing"><strong>スクリーンショット未掲載：コマツールバーの拡大</strong> 2行のツールバーと注釈ツールバーを切り出したスクリーンショットを、ここに追加する予定です。 </div><figcaption>掲載予定：番号付きの吹き出しを付けたツールバーの各コントロール。</figcaption></figure><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>自動分割で枠が置き換わった。</strong> 検出は上書きします。コマテンプレートを使うか、最初の分割が成功した後に手作業で編集してください。</li><li><strong>ページに画像がない。</strong> 検出が無効になり、ステージには空の状態が表示されます。欠けている言語フォルダを追加するか、巻の設定で割り当ててください。</li><li><strong>WebP のページは検出されない。</strong> WebP は表示されますが、検出用にデコードされません。JPEG または PNG に変換してください。</li><li><strong>テンプレート適用後にコマノートが消えた。</strong> テンプレートのコマ数が異なっていたためコマノートが破棄され、ページノートは保持されました。必要ならバックアップから復元してください。</li><li><strong>「未保存の変更」が消えない。</strong> 確認モードになっています。<strong>✓</strong> または <code>Enter</code> を押してください。<strong>×</strong> で破棄できます。</li><li><strong>マークが見えない。</strong> 注釈レイヤーが非表示か、コマのフィルターが有効です。<strong>注釈：表示中</strong> を確認してください。</li></ul><h2 id="スクリーンショット未掲載" tabindex="-1">スクリーンショット未掲載 <a class="header-anchor" href="#スクリーンショット未掲載" aria-label="Permalink to &quot;スクリーンショット未掲載&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>必要な箇所</th></tr></thead><tbody><tr><td>ツールバーの拡大</td><td>1行目と2行目のコントロール</td></tr><tr><td>注釈ツールバーの拡大</td><td>ツールアイコンと色見本</td></tr><tr><td>コマテンプレートのダイアログ</td><td>テンプレートの保存 / 適用コントロール</td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/compare">比較リーダー</a> — コマは何のためにあるのか。</li><li><a href="/KomaYomi-docs/ja/data-format">データ形式</a> — ページ JSON の契約。</li><li><a href="/KomaYomi-docs/ja/guide/shortcuts">キーボードショートカット</a> — すべてのキーを1つの表に。</li></ul>',10))])}const P=n(g,[["render",h]]);export{x as __pageData,P as default};
